#ifndef PICODIVER_DATA_H
#define PICODIVER_DATA_H

#include <stdint.h>

/* Ported programmatically (not hand-transcribed) from
 * PicoJS/games/picodiver/picodiver-data.js, itself generated by
 * PicoJS's own tools/p8-to-js.js from the original picodiver2.p8 cart
 * (https://github.com/nateProjects/PicoDiver). See the project history
 * for the extraction script -- a Python ast.literal_eval of the JS
 * array literals (mapData/spriteFlags/spriteData are valid Python literal
 * syntax too, hex included), not a reimplementation. */

/* Sheet truncated to its first 8 rows (sprite indices 0-127, pixel rows
 * 0-63) -- the highest sprite index this cart's map data or game logic
 * ever references is 113 (a map tile), confirmed by scanning every value
 * in mapData, not guessed. The real Pico-8 cart's full 128x128 sheet
 * editor canvas always allocates all 16 rows regardless of how many are
 * actually drawn with content; the bottom 8 rows here were genuinely
 * empty padding, not gameplay content, so dropping them is a real size
 * win (8KB), not a content cut -- see M4's docs/picodiver-notes.md for
 * why this was needed (the full 128x128 sheet pushed the resident binary
 * past 64K). picodiver_sprite_flags (256 bytes, unused -- this game's own
 * logic branches on raw sprite-index ranges instead of fget()/fset(),
 * confirmed by reading picodiver.js itself) was dropped from the build
 * entirely for the same reason. */
#define PICODIVER_SHEET_W 128
#define PICODIVER_SHEET_H 64
extern const uint8_t picodiver_sprite_data[PICODIVER_SHEET_W * PICODIVER_SHEET_H];

/* Truncated to 16 rows (of the original cart's 32) for the same reason as
 * the sprite sheet above: both pico_map() call sites in games/picodiver/
 * main.c only ever read rows 0-15 (back()'s row 4-15, shipshow()'s row
 * 0-3) -- confirmed by checking every pico_map() call in this game, not
 * guessed.
 *
 * Banked (lib/pico_bank.h), split out of this same source file into its
 * own picodiver_map_data.c (2026-10-12) -- see that file's own top
 * comment for why only the map data moved and the sprite sheet stayed
 * resident. Valid only while PICODIVER_MAP_PHYSICAL_PAGE is paged in
 * (pico_bank_page_in()/page_out() around each of main.c's own 3 read
 * sites); page 8 picked because it's the one this exact z88dk/ZEsarUX
 * setup has already verified reliable (islander's own banking work hit
 * real, unexplained per-page-number failures on this same toolchain --
 * see z88dk_banking_reference memory's eleventh-module entry -- so this
 * reuses a known-good number rather than picking a fresh untested one;
 * re-verify via ZRCP before trusting it regardless, same discipline). */
#define PICODIVER_MAP_PHYSICAL_PAGE 8
#define PICODIVER_MAP_W 128
#define PICODIVER_MAP_H 16
extern const uint8_t picodiver_map_data[PICODIVER_MAP_W * PICODIVER_MAP_H];

#endif
